// Author: MiYu. A source Zeppelin fixture exercises capacity, native events, boarding, travel and unloading with real handles.
#include "session.h"
#include "setup.h"
#include <bit>
#include <iostream>
using namespace war3;
int wmain(int argc,wchar_t** argv){
    try{
        if(argc<3 || argc>4)throw std::runtime_error("Usage: war3_transport_tests <data-root> <fixture> [flow|capacity|lifecycle|orders|boarding-route|crash]");std::wstring mode=argc>3?argv[3]:L"flow";if(mode!=L"flow" && mode!=L"capacity" && mode!=L"lifecycle" && mode!=L"orders" && mode!=L"boarding-route" && mode!=L"crash")throw std::runtime_error("Unknown transport mode");Archives archives(argv[1]);archives.mountMap(argv[2]);auto world=World::read(archives);auto info=world->data().info;ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info);session.attachWorld(std::move(world));session.audioMuted(true);session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto require=[](bool value,const char* message){if(!value)throw std::runtime_error(message);};auto point=[&](int value){return vm.real(jass::Real::fromInteger(value));};auto carrier=vm.global("carrier"),passenger=vm.global("passenger"),hero=vm.global("hero"),siege=vm.global("siege");auto c=session.units().at(carrier.bits);auto number=[](jass::Real value){return std::bit_cast<float>(value.bits());};auto load=[&](jass::Value target){require(call("IssueTargetOrder",{carrier,vm.string("load"),target}).bits,"Original load order was rejected");session.advance(1);require(call("IsUnitInTransport",{target,carrier}).bits,"Load order did not board its passenger");};require(session.cargoCapacity(carrier.bits)==8 && session.cargoUsed(carrier.bits)==0,"Source Zeppelin capacity was not read");
        if(mode==L"boarding-route"){auto p=session.units().at(passenger.bits);auto real=[](float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));};call("SetUnitPosition",{passenger,point(-500),point(0)});require(call("IssueTargetOrder",{passenger,vm.string("smart"),carrier}).bits && !p->route.empty(),"Boarding pursuit did not start");auto end=p->route.back();auto speed=p->moveSpeed;p->moveSpeed=real(1);WorldPoint detour{p->x,real(number(p->y)+64)};p->route.insert(p->route.begin()+p->waypoint,detour);auto index=p->waypoint;session.advance(.5);require(p->combat.board==carrier.bits && p->waypoint==index && p->route.size()>index && p->route[index].x.bits()==detour.x.bits() && p->route[index].y.bits()==detour.y.bits() && p->route.back().x.bits()==end.x.bits() && p->route.back().y.bits()==end.y.bits(),"Boarding discarded a valid detour");call("SetUnitPosition",{carrier,point(200),point(0)});session.advance(.5);require(!p->route.empty() && (p->route.back().x.bits()!=end.x.bits() || p->route.back().y.bits()!=end.y.bits()),"Boarding retained an out-of-range destination");p->moveSpeed=speed;for(unsigned i=0;i<640 && !call("IsUnitInTransport",{passenger,carrier}).bits;++i)session.advance(1./32);require(call("IsUnitInTransport",{passenger,carrier}).bits && vm.global("loaded_count").bits==1,"Passenger did not reach and board transport");auto next=call("CreateUnit",{call("Player",{vm.integer(0)}),vm.integer(int(ObjectData::code("hfoo"))),point(-500),point(0),point(0)});call("SetUnitPathing",{next,vm.boolean(false)});require(call("IssueTargetOrder",{next,vm.string("smart"),carrier}).bits && session.units().at(next.bits)->combat.board==carrier.bits,"Second boarding order was rejected");call("RemoveUnit",{carrier});session.advance(1./32);auto remaining=session.units().at(next.bits);require(!remaining->combat.board && remaining->route.empty() && !remaining->currentOrder,"Removed transport retained a boarding order");if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"PASS boarding_route_and_moving_transport\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;}
        load(passenger);require(call("IsUnitLoaded",{passenger}).bits && vm.global("loaded_count").bits==1 && vm.global("loaded_event_unit").bits==passenger.bits && vm.global("loaded_event_carrier").bits==carrier.bits && vm.global("loaded_trigger_unit").bits==passenger.bits,"Loaded native context and real manifest disagree");
        if(mode==L"crash"){
            load(hero);auto normal=session.units().at(passenger.bits),champion=session.units().at(hero.bits);call("KillUnit",{carrier});auto id=ObjectData::code("Bchd");require(!normal->transport && !champion->transport && normal->buffs.contains(id) && champion->buffs.contains(id),"Crash did not release and affect passengers");auto& a=normal->buffs.at(id);auto& b=champion->buffs.at(id);require(a.kind==BuffKind::CargoDizzy && !a.dispellable && a.total==60 && b.total==30 && a.moveReduction>.89f && a.attackReduction>.89f,"Crash status lacks source durations or speed penalties");call("UnitRemoveBuffs",{passenger,vm.boolean(true),vm.boolean(true)});require(normal->buffs.contains(id),"Crash status was dispelled");session.advance(30);require(!champion->buffs.contains(id) && normal->buffs.contains(id) && normal->spellMoveFactor()>.1f,"Crash recovery or hero expiration failed");session.advance(31);require(!normal->buffs.contains(id) && normal->spellMoveFactor()==1.f,"Crash status did not expire");require(!GetModuleHandleW(L"Game.dll"),"Game.dll loaded");std::cout<<"PASS crash passenger recovery status\nRESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
        }
        if(mode==L"flow"){
            require(call("IssueTargetOrder",{hero,vm.string("smart"),carrier}).bits,"Smart boarding order was rejected");session.advance(1);require(call("IsUnitInTransport",{hero,carrier}).bits,"Smart boarding did not use the transport");load(siege);require(session.cargoUsed(carrier.bits)==4 && vm.global("loaded_count").bits==3,"Source cargo sizes did not consume one plus one plus two slots");require(!call("IssuePointOrder",{passenger,vm.string("move"),point(1000),point(0)}).bits,"Loaded passenger accepted a world order");require(!session.damageUnit(vm.global("enemy_unit").bits,passenger.bits,10,0,26),"Loaded passenger accepted external damage");require(call("IssuePointOrder",{carrier,vm.string("move"),point(1024),point(0)}).bits,"Loaded carrier could not move");session.advance(5);for(auto unit:{passenger,hero,siege}){auto p=session.units().at(unit.bits);require(number(p->x)==number(c->x) && number(p->y)==number(c->y) && p->hidden(),"Passenger did not travel with its transport");}require(call("IssueTargetOrder",{carrier,vm.string("unload"),passenger}).bits && !call("IsUnitLoaded",{passenger}).bits,"Single-passenger unload failed");require(call("IssueImmediateOrderById",{carrier,vm.integer(852049)}).bits && !call("IsUnitLoaded",{hero}).bits && !call("IsUnitLoaded",{siege}).bits && session.cargoUsed(carrier.bits)==0,"Instant unload-all did not release the manifest");std::cout<<"PASS transport_load_smart_capacity_events_travel_and_unload\n";
        }else if(mode==L"orders"){
            load(hero);load(siege);require(call("IssuePointOrderById",{carrier,vm.integer(852048),point(int(number(c->x))),point(int(number(c->y)))}).bits,"Source unload-all point order was rejected");session.advance(1./32);require(c->cargo.size()==2 && c->cargoDrop.has_value() && c->currentOrder==852048,"Normal unload did not preserve its source order and interval");session.advance(1./32);require(c->cargo.size()==2,"Normal unload ignored the source hold interval");require(call("IssuePointOrder",{carrier,vm.string("move"),point(1024),point(0)}).bits && !c->cargoDrop,"Movement did not cancel the unload queue");std::cout<<"PASS unload_all_order_interval_and_cancel\n";
        }else if(mode==L"capacity"){
            load(hero);load(siege);for(unsigned i=0;i<4;++i){auto unit=call("CreateUnit",{call("Player",{vm.integer(0)}),vm.integer(int(ObjectData::code("hfoo"))),point(int(number(c->x))),point(int(number(c->y))),point(0)});load(unit);}require(session.cargoUsed(carrier.bits)==8,"Full source hold did not account for all slot costs");auto extra=call("CreateUnit",{call("Player",{vm.integer(0)}),vm.integer(int(ObjectData::code("hfoo"))),point(int(number(c->x))),point(int(number(c->y))),point(0)});require(!call("IssueTargetOrder",{carrier,vm.string("load"),extra}).bits && !call("IsUnitLoaded",{extra}).bits,"Full hold accepted an extra passenger");require(!call("IssueTargetOrder",{carrier,vm.string("load"),carrier}).bits,"Transport accepted recursive loading");std::cout<<"PASS cargo_size_full_capacity_and_recursive_rejection\n";
        }else{
            call("RemoveUnit",{passenger});require(c->cargo.empty() && session.cargoUsed(carrier.bits)==0,"Removed passenger left a manifest entry");load(hero);call("KillUnit",{carrier});require(!call("IsUnitLoaded",{hero}).bits && c->cargo.empty(),"Carrier death orphaned a loaded unit");require(!session.units().at(hero.bits)->hidden(),"Carrier death left its passenger hidden");std::cout<<"PASS passenger_removal_and_carrier_death_detach\n";
        }
        if(GetModuleHandleW(L"Game.dll"))throw std::runtime_error("Game.dll loaded");std::cout<<"RESULT passed=1 failed=0 game_dll_loaded=false\n";return 0;
    }catch(const std::exception& error){std::cerr<<"FAIL "<<error.what()<<'\n';return 1;}
}
